import java.util.Arrays;
import java.util.List;

public class RecordParserTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    /** Returns "lineNumber|lineText|message" for a thrown ParseException, or a description of what happened instead. */
    static String describeThrow(RecordParser parser, String line, int lineNumber) {
        try {
            String result = parser.parse(line, lineNumber);
            return "no exception, returned " + result;
        } catch (ParseException e) {
            return e.getLineNumber() + "|" + e.getLineText() + "|" + e.getMessage();
        } catch (Throwable t) {
            return "wrong throwable " + t.getClass().getName();
        }
    }

    public static void main(String[] args) {
        RecordParser parser = new RecordParser();

        check("ParseException is checked, not a RuntimeException",
                true,
                Exception.class.isAssignableFrom(ParseException.class)
                        && !RuntimeException.class.isAssignableFrom(ParseException.class));

        try {
            check("parse of a clean line", "Ada:36", parser.parse("Ada,36", 1));
            check("parse trims spaces around both fields", "Bob:7", parser.parse(" Bob , 07 ", 2));
            check("parse accepts age zero", "Cy:0", parser.parse("Cy,0", 3));
        } catch (ParseException e) {
            System.out.println("FAIL  parse of a valid line threw " + e);
            failures += 3;
        }

        check("missing comma throws with the line number and text",
                "4|Ada|line 4: Ada", describeThrow(parser, "Ada", 4));
        check("non-numeric age throws", "5|Ada,x|line 5: Ada,x", describeThrow(parser, "Ada,x", 5));
        check("empty name throws", "6| ,36|line 6:  ,36", describeThrow(parser, " ,36", 6));
        check("negative age throws", "7|Ada,-3|line 7: Ada,-3", describeThrow(parser, "Ada,-3", 7));
        check("too many fields throws", "8|Ada,36,x|line 8: Ada,36,x", describeThrow(parser, "Ada,36,x", 8));
        check("parse alone does not count errors", 0, parser.getErrorCount());

        RecordParser batch = new RecordParser();
        List<String> lines = Arrays.asList("Ada,36", "oops", "Bob,7", "Cy,-1", "  Dee  ,4");
        check("parseAll keeps the good records", "[Ada:36, Bob:7, Dee:4]", String.valueOf(batch.parseAll(lines)));
        check("parseAll counted the skipped lines", 2, batch.getErrorCount());
        check("parseAll on an empty list", "[]", String.valueOf(batch.parseAll(Arrays.asList())));
        check("error count survives an empty run", 2, batch.getErrorCount());
        check("second parseAll adds to the good records", "[Eve:20]", String.valueOf(batch.parseAll(Arrays.asList("bad", "Eve,20"))));
        check("error count adds up across runs", 3, batch.getErrorCount());

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

